// CAPI: construye el payload del evento Lead con email/telefono hasheados
// (SHA-256, requisito de Meta). El event_id es el MISMO que disparo el Pixel en
// el navegador (columna meta_event_id) -> Meta deduplica y no cuenta doble.
// Nota: el Code node necesita el modulo 'crypto'. Si tu n8n lo bloquea, arranca
// con NODE_FUNCTION_ALLOW_BUILTIN=crypto (o *).
const crypto = require('crypto');
const rec = $('Webhook (Supabase INSERT)').item.json.body.record;

const sha256 = (v) => v ? crypto.createHash('sha256').update(String(v).trim().toLowerCase()).digest('hex') : undefined;
const sha256Phone = (v) => {
  const digits = v ? String(v).replace(/[^0-9]/g, '') : '';
  return digits ? crypto.createHash('sha256').update(digits).digest('hex') : undefined;
};

const user_data = {};
if (rec.correo) user_data.em = [sha256(rec.correo)];
if (rec.whatsapp) user_data.ph = [sha256Phone(rec.whatsapp)];
if (rec.fbc) user_data.fbc = rec.fbc;
if (rec.fbp) user_data.fbp = rec.fbp;

const payload = {
  data: [{
    event_name: 'Lead',
    event_time: Math.floor(Date.now() / 1000),
    event_id: rec.meta_event_id,
    action_source: 'website',
    event_source_url: rec.url,
    user_data,
    custom_data: { content_name: rec.servicio }
  }]
};

// Para validar en Events Manager -> Test Events, define META_TEST_EVENT_CODE:
if (process.env.META_TEST_EVENT_CODE) {
  payload.test_event_code = process.env.META_TEST_EVENT_CODE;
}

return [{ json: payload }];
